function $(id){return document.getElementById(id)} function qsa(sel){return Array.from(document.querySelectorAll(sel))} function round(n){return Math.round(n*10)/10}
function parseCat(v){if(v==null)return{n:null,src:''};let d=String(v),lit=null;if(d.includes('|')){[d,lit]=d.split('|')}
 if(/^(IND|SEV)EXT$/.test(d)){const q=parseCat(d.slice(0,-3)+(lit?'|'+lit:''));q.src='EXT';return q}
 if(d==='NA')return{n:null,src:'NA',lit:lit||'NA'};if(d==='IND')return{n:2.5,src:'',lit:lit||'—'};if(d==='SEV')return{n:3.5,src:'',lit:lit||'según gravedad'};if(d==='3/4')return{n:3.5,src:'',lit:lit||'3/4'};
 let m=d.match(/^I(\d)C(\d)$/);if(m)return{n:Number(m[1]),src:'',lit:lit||`I ${m[1]} / C ${m[2]}`};m=d.match(/^(\d)(.*)$/);return{n:Number(m[1]),src:m[2]||'',lit}}
function catLabel(v){const p=parseCat(v);if(p.lit)return p.lit+(p.src==='EXT'?' (ext.)':'');if(p.src==='NA')return 'NA';return p.n+(p.src==='EXT'?' (ext.)':'')}
function maxLabel(n,route){if(n===3.5)return route==='contraception'?'3/4':'según gravedad';if(n===2.5)return 'individualizar';return String(n)}
function init(){renderCervantes();bindEvents();updateSummary()}
function bindEvents(){
 if($('btn-start')) $('btn-start').addEventListener('click',()=>goTo('station-context'));
 $('age').addEventListener('input',renderContextDynamic);$('amenorrhea').addEventListener('change',renderContextDynamic);$('btn-context').addEventListener('click',validateContext);
 $('hasPartner').addEventListener('change',()=>{renderCervantes();computeCervantes()});
 $('btn-cervantes-continue').addEventListener('click',()=>{state.naturalFinal=false;state.treatment=null;prepareRoute();unlockStation('station-route');goTo('station-route')});
 $('btn-finish-natural').addEventListener('click',()=>{invalidateFrom('station-route');state.naturalFinal=true;state.route='natural';state.treatment='natural';renderTreatmentOptions();generateReports();unlockStation('station-report');goTo('station-report');updateSummary()});
 $('btn-route').addEventListener('click',()=>{invalidateFrom('station-treatment');state.eligibility=null;renderEligibility();unlockStation('station-eligibility');goTo('station-eligibility')});
 $('btn-eligibility').addEventListener('click',validateEligibility);
 $('btn-treatment').addEventListener('click',()=>{if(!state.treatment){flash($('treatment-conclusion'),'Seleccione una opción terapéutica para generar el informe.');return}generateReports();unlockStation('station-report');goTo('station-report')});
 $('btn-reset').addEventListener('click',()=>location.reload());
 qsa('.copy-btn').forEach(btn=>btn.addEventListener('click',()=>copyText(btn.dataset.copy,btn)));
 qsa('.nav-item').forEach(btn=>btn.addEventListener('click',()=>{if(!btn.classList.contains('locked'))goTo(btn.dataset.target)}))
}

/* ---------- Situación ---------- */
function isLateSafety(age){return Number(age)>=60}
function lateSafetyText(){return 'Edad ≥60 años: la tabla resumen de la AEEM asigna a la THM sistémica 2/3*** entre los 60 y los 69 años (categoría 3 si se inicia por encima de los 10 años de la menopausia) y categoría 3 a partir de los 70 años.'}
function lateCategory3Text(){return 'AEEM, tabla resumen (edad y duración): 60-69 años, 2/3*** — continuación de la THM categoría 2; inicio de la THM por encima de los 10 años de la menopausia categoría 3. > 70 años: categoría 3. Tibolona: 2 (salvo > 70 años con >5 años de uso: 3).'}
function amenorrheaLabel(v){return({lt12:'<12 meses',y1to5:'1–5 años',y5to10:'5–10 años',gt10:'>10 años'})[v]||'pendiente'}
function renderContextDynamic(){const age=Number($('age').value||0), amen=$('amenorrhea').value, zone=$('context-dynamic');const prevC=document.querySelector('input[name="needContraception"]:checked')?.value, prevU=document.querySelector('input[name="hasUterus"]:checked')?.value;zone.innerHTML='';$('context-conclusion').className='conclusion empty';$('context-conclusion').textContent='Complete edad y tiempo de amenorrea para definir la ruta inicial.';if(age&&age<40){zone.innerHTML='<div class="danger-box"><strong>Fuera de esta herramienta.</strong><br>Paciente menor de 40 años: valorar IOP/menopausia precoz en módulo específico.</div>';return} if(!amen)return;const warn=isLateSafety(age)?`<div class="warning-box"><strong>Advertencia de seguridad.</strong><br>${lateSafetyText()}</div>`:'';if(amen==='lt12'){zone.innerHTML=warn+'<div class="card"><label class="field-label">Amenorrea &lt;12 meses: ¿precisa anticoncepción?</label><p class="hint">Referencia habitual: hasta 12 meses de amenorrea si ≥50 años y 24 meses si &lt;50 años.</p><div class="radio-stack"><label><input type="radio" name="needContraception" value="yes"> Sí, precisa anticoncepción</label><label><input type="radio" name="needContraception" value="no"> No precisa anticoncepción</label></div></div><div id="uterus-zone"></div>';qsa('input[name="needContraception"]').forEach(r=>r.addEventListener('change',e=>{state.needsContraception=e.target.value==='yes';if(state.needsContraception){$('uterus-zone').innerHTML=''}else renderUterusQuestion($('uterus-zone'))}))}else{zone.innerHTML=warn+'<div id="uterus-zone"></div>';renderUterusQuestion($('uterus-zone'))}
 if(prevC){const r=document.querySelector(`input[name="needContraception"][value="${prevC}"]`);if(r){r.checked=true;r.dispatchEvent(new Event('change'))}}
 if(prevU){const r=document.querySelector(`input[name="hasUterus"][value="${prevU}"]`);if(r)r.checked=true}}
function renderUterusQuestion(container){container.innerHTML='<div class="card"><label class="field-label">¿Tiene útero?</label><div class="radio-stack"><label><input type="radio" name="hasUterus" value="yes"> Sí, precisa protección endometrial</label><label><input type="radio" name="hasUterus" value="no"> No, histerectomizada</label></div></div>';qsa('input[name="hasUterus"]').forEach(r=>r.addEventListener('change',e=>state.hasUterus=e.target.value==='yes'))}
function validateContext(){const age=Number($('age').value||0), amen=$('amenorrhea').value;if(!age||!amen){flash($('context-conclusion'),'Debe indicar edad y tiempo en amenorrea.');return} if(age>100||!Number.isInteger(age)){flash($('context-conclusion'),'Revise la edad: debe ser un número entero de años.');return} if(age<40){$('context-conclusion').className='conclusion red';$('context-conclusion').innerHTML='<h3>Fuera de calculadora</h3>Paciente menor de 40 años. Valorar IOP/menopausia precoz.';updateSummary();return}state.age=age;state.amenorrhea=amen;state.continueLate=isLateSafety(age);state.hasUterus=null;state.needsContraception=null;if(amen==='lt12'){const sel=document.querySelector('input[name="needContraception"]:checked');if(!sel){flash($('context-conclusion'),'En amenorrea <12 meses debe indicar si precisa anticoncepción.');return}state.needsContraception=sel.value==='yes';if(!state.needsContraception){const uterus=document.querySelector('input[name="hasUterus"]:checked');if(!uterus){flash($('context-conclusion'),'Si no precisa anticoncepción, indique si tiene útero.');return}state.hasUterus=uterus.value==='yes'}}else{const uterus=document.querySelector('input[name="hasUterus"]:checked');if(!uterus){flash($('context-conclusion'),'Debe indicar si tiene útero para seleccionar la THM.');return}state.hasUterus=uterus.value==='yes'}invalidateFrom('station-route');$('context-conclusion').className=state.continueLate?'conclusion amber':'conclusion';$('context-conclusion').innerHTML='<h3>Situación validada</h3>'+contextText()+(state.continueLate?'<p><strong>Advertencia:</strong> '+lateSafetyText()+'</p>':'')+' Se habilita la escala Cervantes SFv2.';unlockStation('station-cervantes');updateSummary();goTo('station-cervantes')}
function contextText(){const label=amenorrheaLabel(state.amenorrhea);if(state.amenorrhea==='lt12'){return state.needsContraception?`Paciente de ${state.age} años, amenorrea ${label}, con necesidad anticonceptiva: ruta anticonceptiva.`:`Paciente de ${state.age} años, amenorrea ${label}, sin necesidad anticonceptiva, ${state.hasUterus?'con útero':'sin útero'}: ruta THM según elegibilidad.`}return `Paciente de ${state.age} años, amenorrea ${label}, ${state.hasUterus?'con útero':'sin útero'}.`}

/* ---------- Cervantes ---------- */
